package com.gymmind.ai.domain; import java.util.*; public final class ContextBudgeter {private ContextBudgeter(){} public static List<ContextSegment> select(List<ContextSegment> input,int maxChars){if(input==null||maxChars<=0)return List.of();Map<String,Integer> counts=new HashMap<>();List<ContextSegment> out=new ArrayList<>();int used=0;for(ContextSegment s:input){if(s==null||s.text()==null||counts.getOrDefault(s.documentId(),0)>=2)continue;int n=s.text().length();if(used+n>maxChars)break;out.add(s);counts.merge(s.documentId(),1,Integer::sum);used+=n;if(out.size()>=8)break;}return out.size()<5&&input.size()>=5?out:out;}}
